// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// Função auxiliar para sortear uma mensagem da lista
function pick(arr) {
  if (!arr || !arr.length) return "";
  return arr[Math.floor(Math.random() * arr.length)];
}

// 1. Extrai a lista de clientes e a lista de investimentos do nó Merge
const clientes = $json.clientes ?? $json.body?.clientes ?? $('Receber Clientes (Webhook)').first()?.json?.body?.clientes ?? [];
const investimentos = $json.investimentos ?? $('Converter CSV em JSON').first()?.json?.investimentos ?? [];

// 2. Processa cada cliente
const resultados = clientes.map(c => {
  const nome = c.nome;
  const email = c.email;
  const perfil = c.perfil;

  // Converte "R$ 12.500,00" para número inteiro 12500
  const numeros = String(c.saldo || "").replace(/[^\d]/g, "");
  const saldoNum = numeros ? Math.floor(Number(numeros) / 100) : 0;

  // Filtra os investimentos compatíveis com o perfil do cliente
  const opcoesPerfil = investimentos.filter(inv => 
    String(inv.perfil).trim().toLowerCase() === String(perfil).trim().toLowerCase()
  );

  // Filtra as opções cujo valor mínimo cabe no saldo do cliente
  const opcoesValidas = opcoesPerfil.filter(inv => saldoNum >= Number(inv.minimo));

  let escolhido = null;
  let motivo = "saldo_ok";

  if (opcoesValidas.length > 0) {
    // Escolhe uma opção válida (dá preferência a opções com bom retorno)
    escolhido = opcoesValidas.find(inv => inv.produto.includes("CDB")) || opcoesValidas[0];
    motivo = "saldo_ok";
  } else if (opcoesPerfil.length > 0) {
    escolhido = opcoesPerfil[0];
    motivo = "saldo_insuficiente";
  } else {
    motivo = "perfil_nao_encontrado";
  }

  // Formata o valor mínimo para exibição em Real (ex: 1.000,00)
  const minimoFmt = escolhido && escolhido.minimo 
    ? Number(escolhido.minimo).toLocaleString('pt-BR', { minimumFractionDigits: 2 }) 
    : "0,00";

  // Gera as opções de mensagens personalizadas
  let mensagens = [];
  if (escolhido && motivo === "saldo_ok") {
    mensagens = [
      `Olá ${nome}! Pelo seu perfil (${perfil}), uma boa opção é **${escolhido.produto}** (mínimo R$ ${minimoFmt}). Com seu saldo atual (${c.saldo}), você já consegue investir. Rentabilidade: ${escolhido.rentabilidade}.`,
      `Oi ${nome}! Recomendação para perfil ${perfil}: **${escolhido.produto}** (mínimo R$ ${minimoFmt}). Seu saldo (${c.saldo}) já atende o mínimo. Rentabilidade: ${escolhido.rentabilidade}.`,
      `${nome}, indo direto ao ponto: para o perfil ${perfil}, **${escolhido.produto}** (mínimo R$ ${minimoFmt}). Você tem ${c.saldo}, então dá pra aplicar. Rentabilidade: ${escolhido.rentabilidade}.`
    ];
  } else if (escolhido && motivo === "saldo_insuficiente") {
    mensagens = [
      `Olá ${nome}! Para o seu perfil (${perfil}), a opção recomendada é **${escolhido.produto}** (mínimo R$ ${minimoFmt}). No momento seu saldo é ${c.saldo}. Continue acumulando para investir!`
    ];
  } else {
    mensagens = [
      `Olá ${nome}! Estamos atualizando nossas opções para o perfil ${perfil}.`
    ];
  }

  return {
    nome,
    email,
    perfil,
    saldo_texto: c.saldo,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens),
  };
});

// 3. Retorna o resultado final estruturado
return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];

