const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// Retorna UM ITEM por cliente (necessário para o n8n processar cada um na IA/Email)
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida || c.mensagem || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

// 1. Pega os itens retornados pela IA e os dados originais dos clientes
const items = $input.all();

// Busca o nó anterior que tem os dados do cliente (email_to, nome, etc.)
let clientesOriginais = [];
try {
  clientesOriginais = $('Preparar Itens e Briefing IA').all();
} catch (e) {
  try {
    clientesOriginais = $('Code in JavaScript2').all();
  } catch (err) {
    clientesOriginais = [];
  }
}

// 2. Processa cada item gerado pela IA
const out = items.map((item, index) => {
  // Pega os dados do cliente correspondente
  const j = clientesOriginais[index]?.json || {};
  const to = j.email_to || "";

  // Extrai o texto gerado pela IA (suporta diferentes formatos de retorno)
  let rawText = "";
  if (item.json?.content?.[0]?.text) {
    rawText = item.json.content[0].text;
  } else if (item.json?.output?.[0]?.content?.[0]?.text) {
    rawText = item.json.output[0].content[0].text;
  } else if (item.json?.text) {
    rawText = item.json.text;
  } else if (typeof item.json === "string") {
    rawText = item.json;
  } else {
    rawText = JSON.stringify(item.json);
  }

  // Tenta extrair JSON caso a IA tenha retornado em formato json (```json ... ```)
  const cleanJson = rawText.replace(/```json/gi, "").replace(/```/g, "").trim();
  let parsed = null;
  try {
    parsed = JSON.parse(cleanJson);
  } catch (e) {
    parsed = null;
  }

  const subject = parsed?.subject || `Sugestão de Investimento: ${j.recomendacao?.produto || 'Oportunidade para seu Perfil'}`;
  const text_body = parsed?.text_body || rawText;
  const html_body = parsed?.html_body || `<p>${text_body.replace(/\n\n/g, '</p><p>').replace(/\n/g, '<br>')}</p>`;

  return {
    json: {
      ok: true,
      to,
      subject,
      text_body,
      html_body,

      // (opcional) manter alguns campos úteis pra debug/aula
      meta: {
        nome: j.nome,
        perfil: j.perfil,
        produto: j.recomendacao?.produto,
        minimo: j.recomendacao?.minimo,
        rentabilidade: j.recomendacao?.rentabilidade,
        motivo: j.motivo
      }
    }
  };
});

return out;
